class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        visited = {}

        list_length = len(nums)
        for i in range(list_length):
            curr = nums[i]
            nr = target - curr
            if nr in visited:
                return [visited[nr], i]

            visited[curr] = i

        return []

class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        visited = set()
        left = 0
        max_length = 0

        s_length = len(s)
        for i in range(s_length):
            while s[i] in visited:
                visited.remove(s[left])
                left += 1

            visited.add(s[i])
            curr = i - left + 1
            if curr > max_length:
                max_length = curr

        return max_length

class Solution:
    def maxArea(self, height: List[int]) -> int:
        left = 0
        height_length = len(height)
        right = height_length - 1

        maximum = 0
        while left < right:
            width = right - left
            minim_height = min(height[left], height[right])

            curr = width * minim_height
            if curr > maximum:
                maximum = curr

            if height[left] < height[right]:
                left += 1
            else:
                right -= 1


        return maximum

class Solution:
    def threeSum(self, nums: list[int]) -> list[list[int]]:
        ret = []

        nums.sort()
        nums_length = len(nums)
        for i in range(nums_length):
            if i > 0 and nums[i] == nums[i-1]:
                continue
            left = i + 1
            right = nums_length - 1

            while left < right:
                sum3 = nums[i] + nums[left] + nums[right]
                if sum3 > 0:
                    right -= 1
                elif sum3 < 0:
                    left += 1
                else:
                    ret.append([nums[i], nums[left], nums[right]])

                    # skip the duplicates
                    left += 1
                    while left < right and nums[left] == nums[left - 1]:
                        left += 1

        return ret

class Solution:
    def isValid(self, s: str) -> bool:
        stack = []

        s_map = {
            ')': '(', 
            '}': '{', 
            ']': '['
        }

        for c in s:
            if c in s_map:
                curr = '#'
                if stack:
                    curr = stack.pop()

                if s_map[c] != curr:
                    return False

            else:
                stack.append(c)

        return not stack

