class Solution:
    def isSameTree(self, p: Optional[TreeNode], q: Optional[TreeNode]) -> bool:
        if not p and not q:
            return True

        if not p or not q or p.val != q.val:
            return False

        if self.isSameTree(p.left, q.left) and self.isSameTree(p.right, q.right):
            return True
        return False

class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        min_price = float('inf')
        max_profit = 0

        for p in prices:
            if p < min_price:
                min_price = p
            elif p - min_price > max_profit:
                max_profit = p - min_price

        return max_profit

class Solution:
    def isPalindrome(self, s: str) -> bool:
        def is_alphanumeric(c):
            if ('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9'):
                return True
            return False
        s_length = len(s)
        left = 0
        right = s_length - 1

        while left < right:
            while left < right and not is_alphanumeric(s[left]):
                left += 1

            while left < right and not is_alphanumeric(s[right]):
                right -= 1

            if s[left].lower() != s[right].lower():
                return False

            left += 1
            right -= 1

        return True

class Solution:
    def longestConsecutive(self, nums: List[int]) -> int:
        nr = set(nums)
        seq_max = 0

        for i in nr:
            if (i - 1) not in nr:
                curr_length = 1
                curr = i

                while (curr + 1) in nr:
                    curr += 1
                    curr_length += 1

                if curr_length > seq_max:
                    seq_max = curr_length

        return seq_max

class Solution:
    def findMin(self, nums: List[int]) -> int:
        left = 0
        nums_length = len(nums)
        right = nums_length - 1

        while left < right:
            mid = (left + right) // 2

            if nums[mid] > nums[right]:
                left = mid + 1
            else:
                right = mid

        return nums[left]

class MinStack:

    def __init__(self):
        self.stack = []
        self.min_stack = []

    def push(self, value: int) -> None:
        self.stack.append(value)
        if not self.min_stack:
            self.min_stack.append(value)
        else:
            curr = self.min_stack[-1]
            if value < curr:
                self.min_stack.append(value)
            else:
                self.min_stack.append(curr)

    def pop(self) -> None:
        if self.stack:
            self.stack.pop()
            self.min_stack.pop()

    def top(self) -> int:
        if self.stack:
            return self.stack[-1]
            return None

    def getMin(self) -> int:
        if self.min_stack:
            return self.min_stack[-1]
        return None


