class Solution:
    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
        curr = root
        while curr:
            if p.val > curr.val and q.val > curr.val:
                curr = curr.right
            elif p.val < curr.val and q.val < curr.val:
                curr = curr.left
            else:
                return curr

class Solution:
    def productExceptSelf(self, nums: List[int]) -> List[int]:
        nr = len(nums)

        nums1 = [1] * nr
        nums2 = [1] * nr
        ret = [1] * nr

        for i in range(1, nr):
            nums1[i] = nums1[i-1] * nums[i - 1]

        for i in range (nr - 2, -1, -1):
            nums2[i] = nums2[i + 1] * nums[i + 1]

        for i in range(nr):
            ret[i] = nums1[i] * nums2[i]

        return ret

class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        s_letters = {}
        t_letters = {}

        if len(s) != len(t):
            return False

        for l in s:
            if l in s_letters:
                s_letters[l] += 1
            else:
                s_letters[l] = 1

        for l in t:
            if l in t_letters:
                t_letters[l] += 1
            else:
                t_letters[l] = 1

        if s_letters == t_letters:
            return True
        return False

class Solution:
    def topKFrequent(self, nums: List[int], k: int) -> List[int]:
        freq = {}
        for i in nums:
            if i in freq:
                freq[i] += 1
            else:
                freq[i] = 1

        pairs = []
        for nr, nr_app in freq.items():
            pairs.append((nr_app, nr))

        pairs.sort(reverse=True)

        ret = []
        for i in range(k):
            ret.append(pairs[i][1])

        return ret

class Solution:
    def characterReplacement(self, s: str, k: int) -> int:
        left = 0
        s_length = len(s)
        right = s_length - 1

        freq = {}
        max_length = 0
        max_freq = 0

        for i in range(s_length):
            curr = s[i]
            freq[curr] = freq.get(curr, 0) + 1
            if max_freq < freq[curr]:
                max_freq = freq[curr]

            window_length = i - left + 1
            while window_length - max_freq > k:
                c1 = s[left]
                freq[c1] -= 1
                left += 1
                window_length = i - left + 1

            if window_length > max_length:
                max_length = window_length

        return max_length

